mapper.select:
SELECT 

WHERE v.post_id = #{postId}
ORDER BY v.id DESC
LIMIT #{limit}

mapper.delete:
DELETE FROM post_versions
 WHERE post_id = #{postId}
   AND reason <> 'PUBLISH'
   AND id NOT IN (
     SELECT id FROM (
       SELECT id FROM post_versions
        WHERE post_id = #{postId} AND reason <> 'PUBLISH'
        ORDER BY id DESC
        LIMIT #{keep}
     ) keep_rows
   )
